  aliases, search_keywords, osm_type, osm_id, is_verified, is_active, created_at, updated_at
)
SELECT 'road_segment', 'Marcos Avenue Extension', NULL, 'Marcos Avenue Extension', 6.1248747, 125.1232760, '["Marcos Ave Extension"]', '["marcos avenue extension","marcos avenue extension 151460700","marcos ave extension","general santos city"]', 'way', '151460700', 1, 1, NOW(), NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM gensan_dispatch_destinations
  WHERE osm_type = 'way' AND osm_id = '151460700'
);
UPDATE gensan_dispatch_destinations
SET destination_type = 'road_segment', name = 'Marcos Avenue Extension',
    barangay = NULL, display_label = 'Marcos Avenue Extension',
    latitude = 6.1248747, longitude = 125.1232760,
    aliases = '["Marcos Ave Extension"]', search_keywords = '["marcos avenue extension","marcos avenue extension 151460700","marcos ave extension","general santos city"]',
    is_verified = 1, is_active = 1, updated_at = NOW()
WHERE osm_type = 'way' AND osm_id = '151460700';
SET @destination_id = (SELECT id FROM gensan_dispatch_destinations WHERE osm_type = 'way' AND osm_id = '151460700' ORDER BY id ASC LIMIT 1);
